<?php require 'config.php'; require_login(); $uid=$_SESSION['uid']; $u=cur_u($pdo,$uid);
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $a=$_POST['action'] ?? '';
  if ($a==='allowance') { $pdo->prepare('UPDATE users SET allowance=?,allowance_day=? WHERE id=?')->execute([max(0,(float)($_POST['amount'] ?? 0)),max(1,min(28,(int)($_POST['day'] ?? 1))),$uid]); flash('Allowance saved.'); }
  elseif ($a==='auto') { $day=max(1,min(28,(int)$u['allowance_day'])); $d=date('Y-m-').str_pad($day,2,'0',STR_PAD_LEFT); if ($d<=date('Y-m-d')) $d=date('Y-m-',strtotime('+1 month')).str_pad($day,2,'0',STR_PAD_LEFT);
    if ($u['allowance']>0) { $pdo->prepare("INSERT INTO recurring(user_id,type,category,amount,description,frequency,next_date) VALUES(?,'income','Allowance',?,'Allowance','monthly',?)")->execute([$uid,$u['allowance'],$d]); flash('Allowance will be recorded automatically every month.'); } else flash('Set your allowance amount first.'); }
  elseif ($a==='tuition') { $n=mb_substr(trim($_POST['item'] ?? ''),0,80); $am=(float)($_POST['amount'] ?? 0); $dt=DateTime::createFromFormat('Y-m-d',$_POST['due'] ?? ''); if ($n!==''&&$am>0&&$dt) { $pdo->prepare('INSERT INTO tuition(user_id,item,amount,paid,due_date) VALUES(?,?,?,?,?)')->execute([$uid,$n,$am,max(0,(float)($_POST['paid'] ?? 0)),$dt->format('Y-m-d')]); flash('Fee item added.'); } else flash('Fill in the item, amount and due date.'); }
  elseif ($a==='pay') { $pdo->prepare('UPDATE tuition SET paid=LEAST(amount,paid+?) WHERE id=? AND user_id=?')->execute([max(0,(float)$_POST['amount']),(int)$_POST['id'],$uid]); flash('Payment recorded.'); }
  elseif ($a==='del') { $pdo->prepare('DELETE FROM tuition WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]); }
  header('Location: student.php'); exit; }
$u=cur_u($pdo,$uid); $cash=total_cash($pdo,$uid); $day=min((int)$u['allowance_day'],(int)date('t'));
$next=strtotime(date('Y-m-').str_pad($day,2,'0',STR_PAD_LEFT)); if ($next<=strtotime(date('Y-m-d'))) $next=strtotime(date('Y-m-',strtotime('first day of next month')).str_pad(min((int)$u['allowance_day'],(int)date('t',strtotime('first day of next month'))),2,'0',STR_PAD_LEFT));
$days=max(1,(int)ceil(($next-strtotime(date('Y-m-d')))/86400)); $tu=$pdo->prepare('SELECT * FROM tuition WHERE user_id=? ORDER BY due_date'); $tu->execute([$uid]);
$focus=['Accommodation'=>['rent','accommodation','hostel'],'Food'=>['food'],'Transport'=>['transport'],'Books & supplies'=>['books','supplies','stationery']];
page_head('Student mode'); ?><h1>Student mode</h1>
<div class="card"><h2 style="margin-top:0">Until my next allowance</h2><?php if ($u['allowance']>0): ?><p class="verdict"><?= $days ?> day(s) to go (<?= e(date('D j M',$next)) ?>)</p>
<p>You have <b><?= money($cash) ?></b>. To make it last, spend no more than <b class="<?= $cash<=0?'neg':'' ?>"><?= money(max(0,$cash)/$days) ?></b> a day.</p><?php else: ?><p>Set your allowance below to see how much you can spend each day until the next one.</p><?php endif; ?></div>
<form method="post" class="card narrow"><?= csrf() ?><input type="hidden" name="action" value="allowance"><h2 style="margin-top:0">My allowance</h2><label>Amount per month<input type="number" step="0.01" min="0" name="amount" value="<?= e($u['allowance']) ?>"></label><label>Arrives on day of month (1-28)<input type="number" min="1" max="28" name="day" value="<?= e($u['allowance_day']) ?>"></label><button class="btn">Save</button></form>
<?php if ($u['allowance']>0): ?><form method="post" class="card"><?= csrf() ?><input type="hidden" name="action" value="auto"><p>Record my allowance automatically every month.</p><button class="btn alt">Turn on automatic allowance</button></form><?php endif; ?>
<h2>This month by student need</h2><div class="grid"><?php foreach ($focus as $label=>$keys) { $in=implode(',',array_fill(0,count($keys),'?')); $s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE user_id=? AND type='expense' AND tx_date BETWEEN ? AND ? AND LOWER(category) IN ($in)"); $s->execute(array_merge([$uid,date('Y-m-01'),date('Y-m-t')],$keys)); echo '<div class="card stat"><span>'.e($label).'</span><b>'.money($s->fetchColumn()).'</b></div>'; } ?></div>
<p class="note">Use categories named Rent, Food, Transport and Books, then set limits for them on <a href="budgets.php">Budgets</a> (try the Student template).</p>
<h2>Tuition &amp; fees</h2><div class="card scroll"><table><tr><th>Item</th><th>Due</th><th class="r">Amount</th><th class="r">Paid</th><th class="r">Balance</th><th></th></tr><?php foreach ($tu as $t): ?><tr><td><?= e($t['item']) ?></td><td><?= e($t['due_date']) ?></td><td class="r"><?= money($t['amount']) ?></td><td class="r"><?= money($t['paid']) ?></td><td class="r"><?= money($t['amount']-$t['paid']) ?></td>
<td class="act"><form method="post" class="filters"><?= csrf() ?><input type="hidden" name="action" value="pay"><input type="hidden" name="id" value="<?= $t['id'] ?>"><input type="number" step="0.01" min="0.01" name="amount" placeholder="Paid" style="width:90px"><button class="link" style="color:var(--pri)">Record</button></form><form method="post"><?= csrf() ?><input type="hidden" name="action" value="del"><input type="hidden" name="id" value="<?= $t['id'] ?>"><button class="link">Delete</button></form></td></tr><?php endforeach; ?></table></div>
<form method="post" class="card narrow"><?= csrf() ?><input type="hidden" name="action" value="tuition"><h3 style="margin-top:0">Add a fee</h3><label>Item<input name="item" required maxlength="80" placeholder="e.g. Semester 2 tuition"></label><label>Amount<input type="number" step="0.01" min="0.01" name="amount" required></label><label>Already paid<input type="number" step="0.01" min="0" name="paid" value="0"></label><label>Due date<input type="date" name="due" required></label><button class="btn">Add</button></form><?php page_foot();
